def meaningful_deviations(context: Dict[str, Any]) -> List[str]:
    deviations = []
    for item in context.get("protocol_deviations", []):
        text = str(item)
        lowered = text.lower().strip()
        if lowered == "none" or "no protocol deviation" in lowered:
            continue
        deviations.append(text)
    return deviations


